"""Peptide Encoding Problem: Find substrings of a genome encoding a given amino acid sequence/peptide.
(if the rev comp of a substring encodes the given peptide, return the substring)
"""
from codons import DNA_Codons

dna_seq=""
aa_seq="GKSVNFNHDM"


def reverse_complement(seq):
      """ Swapping adenine with thymine and guanine with cytosine (find the complement).
        Reversing newly generated string."""
      
      mapping = str.maketrans('ATCG', 'TAGC') #complement
      return seq.translate(mapping)[::-1] #reverse

def translate_seq(dna, init_pos=0):
      return [DNA_Codons[dna[pos:pos + 3]] for pos in range(init_pos, len(dna) - 2, 3)] # returns a list, not a string

def find_encoding_seq():
    possible_seq=[]
    for i in range(len(dna_seq)-len(aa_seq)*3+1): #length of dna seq must be 3 times the number of amino acids
        possible_seq.append(dna_seq[i:i+len(aa_seq)*3])

    encoding_seq=[]
    for seq in possible_seq:
        if "".join(translate_seq(seq))==aa_seq: #without "".join(...), you'd be comparing a list to a string, and that comparison is always False
                encoding_seq.append(seq)

    for seq in possible_seq:
        rev_seq=reverse_complement(seq)
        if "".join(translate_seq(rev_seq))==aa_seq:
                encoding_seq.append(seq) #append original seq, not rev_seq

    return encoding_seq

for seq in find_encoding_seq():
      print(seq)